schema.sdl:
directive @key(fields: [String!]!) repeatable on OBJECT | INTERFACE

directive @legacy(term: String @deprecated(reason: "use the query field")) on FIELD

type Query {
  viewer: User!
  species(id: ID!): Species
  searched(term: String!): [Species!]!
  searchedConnection(first: Int, after: String, last: Int, before: String): SpeciesConnection!
  speciesList(first: Int, after: String, last: Int, before: String): SpeciesConnection!
  speciesFiltered(filter: SpeciesFilter!): [Species!]!
  speciesByRarity(rarity: Rarity!): [Species!]!
  searchOld(term: String @deprecated(reason: "use query")): [Species!]!
  trainer: Trainer
}

type Mutation {
  favorite(id: ID!): Species!
}

type Subscription {
  speciesAdded: Species!
  userAdded: User!
}

type User @key(fields: ["id"]) @key(fields: ["name"]) {
  id: ID!
  name: String!
  favorite: Species
  oldName: String @deprecated(reason: "use name")
}

type Trainer {
  id: ID!
  name: String!
  team: SpeciesMove
}

type Species {
  id: ID!
  name: String!
  move: SpeciesMove
  friends: [Species!]
}

type SpeciesMove {
  name: String!
  power: Int
}

type SpeciesConnection {
  edges: [SpeciesEdge!]!
  pageInfo: PageInfo!
}

type SpeciesEdge {
  node: Species!
  cursor: String!
}

type PageInfo {
  hasNextPage: Boolean!
  endCursor: String
}

input SpeciesFilter {
  term: String!
  limit: Int @deprecated(reason: "use take")
}

enum Rarity {
  COMMON @deprecated(reason: "boring")
  RARE
}

inputs.text:
fragment CacheFragment on Species @cache(policy: CacheOnly) {
  id
}

query DeferLabel {
  viewer {
    id
    ... on User @defer(label: "same") {
      name
    }
    ... on User @defer(label: "same") {
      favorite {
        id
      }
    }
  }
}

query DeprecatedInput {
  speciesFiltered(filter: { term: "a", limit: 1 }) {
    id
  }
}

query EmbeddedPageInfo {
  speciesList(first: 1) {
    edges {
      node {
        id
      }
    }
    pageInfo {
      ...PageInfoFields
    }
  }
}

query InputDuplicate {
  speciesFiltered(filter: { term: "a", term: "b" }) {
    id
  }
}

query Introspection {
  __schema {
    types {
      fields {
        type {
          fields {
            type {
              fields {
                name
              }
            }
          }
        }
      }
    }
  }
}

query OptimisticKey @optimisticKey {
  viewer {
    id
    ... on User @optimisticKey {
      name
    }
  }
}

query PaginateTwoFields($first: String) {
  speciesList(first: 1) @paginate(name: "Two_A") {
    edges {
      node {
        id
      }
    }
  }
  searchedConnection(first: 1) @paginate(name: "Two_B") {
    edges {
      node {
        id
      }
    }
  }
}

query SpreadViolation {
  viewer {
    id
    ...SpeciesId
    ... on Species {
      name
    }
  }
}

fragment StreamInFragment on Species {
  friends @stream(initialCount: 1) {
    id
  }
}

query StreamInit {
  searched(term: "a") @stream(initialCount: -1) {
    id
  }
  viewer @stream(initialCount: 0) {
    id
  }
}

subscription SubscriptionTooMany {
  speciesAdded {
    id
  }
  userAdded {
    id
  }
}

query Typename {
  viewer {
    __typename
    id
    species: favorite {
      __typename
      id
    }
  }
}

query VariablePosition($a: String) {
  speciesFiltered(filter: { term: $a }) {
    id
  }
}

query WrongValue {
  species(id: 1.5) {
    id
  }
  searched(term: 3) {
    id
  }
}
